from consumer import consume
class B:
    def __init__(self):
        self.acked = []
    def get(self):
        return 'm'
    def ack(self, m):
        self.acked.append(m)
b = B()
def boom(m):
    raise RuntimeError
try:
    consume(b, boom)
except RuntimeError:
    pass
assert b.acked == []
consume(b, lambda m: None)
assert b.acked == ['m']
